// B. Business requirements live in the vision and scope document; user requirements in use cases/user stories; functional and nonfunctional requirements in the SRS; business rules in their own catalogue.
const DOCUMENTS = {
  'Business requirement': 'VISION_SCOPE',
  'User requirement': 'USER_REQUIREMENTS',
  'Functional requirement': 'SRS',
  'Business rule': 'BUSINESS_RULES_CATALOG',
  'Quality attribute': 'SRS',
};

// C. Product requirements describe the software; project requirements are the other work the project needs (training, documentation, hardware, SLAs…).
const PRODUCT_OR_PROJECT = {
  P1: 'PROJECT',
  P2: 'PROJECT',
  P3: 'PRODUCT',
  P4: 'PROJECT',
  P5: 'PRODUCT',
  P6: 'PROJECT',
};

// D. Development = elicitation, analysis (incl. modelling and negotiating priorities), specification, validation (incl. acceptance criteria); management = baseline, change control, tracing, status.
const ACTIVITIES = {
  D1: 'ELICITATION',
  D2: 'ANALYSIS',
  D3: 'SPECIFICATION',
  D4: 'VALIDATION',
  D5: 'MANAGEMENT',
  D6: 'ANALYSIS',
  D7: 'VALIDATION',
  D8: 'MANAGEMENT',
};

// E. Wiegers Ch.1 "When bad requirements happen to good people".
const PROBLEMS = {
  E1: 'INSUFFICIENT_USER_INVOLVEMENT',
  E2: 'CREEPING_REQUIREMENTS',
  E3: 'AMBIGUOUS_REQUIREMENTS',
  E4: 'GOLD_PLATING',
  E5: 'OVERLOOKED_STAKEHOLDERS',
  E6: 'INACCURATE_PLANNING',
};

